"""Mechanical facts about a diff, worked out by git rather than by an agent.

A commit is marked "skip" only when these facts say every change in it is mechanical, so
everything here errs on the side of "not mechanical".
"""

from __future__ import annotations

import re
from collections import Counter
from pathlib import Path, PurePosixPath
from typing import Any

from review_context import run

LOCKFILES = {
    "yarn.lock",
    "pnpm-lock.yaml",
    "package-lock.json",
    "uv.lock",
    "poetry.lock",
}
# Only comment lines count, so a docstring that says "generated by" doesn't.
GENERATED_HEADER_RE = re.compile(
    r"^\s*(#|//|/\*|\*|<!--|;).*\b(auto-?generated|@generated|do not edit|generated by)\b",
    re.IGNORECASE,
)
MIGRATION_RE = re.compile(r"/migrations/\d{4}_[^/]*\.py$")
TEST_DEF_RE = re.compile(r"^\s*(async\s+)?def test_")
ANSI_RE = re.compile(r"\x1b\[[0-9;]*m")
COLOURED_LINE_RE = re.compile(r"^\x1b\[(?:\d+;)*(\d+)m([+-])")
HUNK_RE = re.compile(r"^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@")

# Moved lines get colours of their own, so they can be told apart from other changes.
MOVED_COLOURS = {"35", "36"}
COLOUR_CONFIG = [
    "color.diff.old=red",
    "color.diff.new=green",
    "color.diff.oldMoved=magenta",
    "color.diff.newMoved=cyan",
    "color.diff.oldMovedAlternative=magenta",
    "color.diff.newMovedAlternative=cyan",
    "color.diff.meta=normal",
    "color.diff.frag=normal",
    "color.diff.func=normal",
    "color.diff.context=normal",
    "diff.wsErrorHighlight=none",
    "core.quotePath=false",
]
# Trailing whitespace and blank lines can't change behaviour. Indentation can (Python, YAML),
# so it is never ignored.
COSMETIC_FLAGS = ["--ignore-space-at-eol", "--ignore-cr-at-eol", "--ignore-blank-lines"]

# Hints for the agents, not verdicts. Matched on changed lines only.
LINE_SIGNALS = {
    "transaction": r"transaction\.atomic|select_for_update|on_commit\(",
    "celery task": r"@(?:\w+\.)*(?:task|shared_task)\b|\.delay\(|\.apply_async\(",
    "raw SQL": r"\bRawSQL\(|\.raw\(|cursor\.execute|RunSQL\(",
    "data migration": r"RunPython\(",
    "bulk write or delete": r"\.delete\(\)|\bbulk_update\(|\bbulk_create\(",
    "settings read": r"\bsettings\.[A-Z][A-Z0-9_]+",
    "feature flag": r"\bfeature_flags?\b|\bswitch_is_active\(|\bflag_is_active\(",
    "broad except": r"except\s*(?:\(?\s*(?:Exception|BaseException)\b[^:]*)?:",
    "current time": r"\b(?:datetime|timezone)\.now\(|\bdate\.today\(|\blocaltime\(",
    "money or rounding": r"\bDecimal\(|\bround\(|minor_unit|_pence\b",
    "permissions": r"permission_classes|has_perm\(|is_superuser|is_staff|login_required|PermissionDenied",
    "skipped test": r"@pytest\.mark\.(?:skip|xfail)|pytest\.skip\(",
    "lint or type suppression": r"#\s*type:\s*ignore|#\s*noqa|#\s*pyright:\s*ignore",
}
LINE_SIGNAL_RES = {label: re.compile(pattern) for label, pattern in LINE_SIGNALS.items()}


def file_facts(repo: Path, base: str, head: str, worktree: Path | None) -> list[dict]:
    """One entry per file changed between `base` and `head`, in diff order."""
    files = _changed_files(repo, base, head)
    lines = _changed_lines(repo, base, head)
    for f in files:
        changed = lines.get(f["path"], [])
        substantive = [line for line in changed if not line["moved"]]
        f["substantive_lines"] = len(substantive)
        f["moved_lines"] = len(changed) - len(substantive)
        f["cosmetic_lines"] = (
            0 if f["binary"] else max(0, f["additions"] + f["deletions"] - len(changed))
        )
        f["test"] = is_test(f["path"])
        f["tests_added"] = sum(
            line["side"] == "+" and bool(TEST_DEF_RE.match(line["text"])) for line in changed
        )
        f["tests_removed"] = sum(
            line["side"] == "-" and bool(TEST_DEF_RE.match(line["text"])) for line in changed
        )
        f["generated"] = generated_reason(f["path"], worktree, f["status"])
        f["signals"] = _signals(f["path"], changed)
        f["mechanical"] = _mechanical_reason(f)
    return files


def summarise(files: list[dict]) -> dict:
    """Totals for a commit, and whether every file in it is mechanical."""
    reasons = Counter(f["mechanical"] for f in files if f["mechanical"])
    return {
        "files": len(files),
        "additions": sum(f["additions"] for f in files),
        "deletions": sum(f["deletions"] for f in files),
        "substantive_lines": sum(f["substantive_lines"] for f in files),
        "code_lines": sum(f["substantive_lines"] for f in files if not f["test"]),
        "moved_lines": sum(f["moved_lines"] for f in files),
        "signals": sorted({s["label"] for f in files for s in f["signals"]}),
        "mechanical": (
            "; ".join(f"{n} × {reason}" for reason, n in reasons.most_common())
            if files and all(f["mechanical"] for f in files)
            else None
        ),
        "paths": [f["path"] for f in files],
    }


def is_test(path: str) -> bool:
    parts = PurePosixPath(path).parts
    name = parts[-1]
    return (
        "tests" in parts
        or "__snapshots__" in parts
        or name.startswith("test_")
        or name.endswith(("_test.py", ".test.ts", ".test.tsx", ".spec.ts", ".spec.tsx"))
    )


def generated_reason(path: str, worktree: Path | None, status: str) -> str | None:
    pure = PurePosixPath(path)
    if pure.name in LOCKFILES:
        return "lockfile (review the manifest change instead)"
    if pure.suffix == ".ambr" or "__snapshots__" in pure.parts:
        # Snapshots show what the output now looks like, so they're worth a look: never mechanical.
        return None
    if MIGRATION_RE.search("/" + path) or status == "D" or worktree is None:
        return None
    target = worktree / path
    try:
        with target.open(errors="replace") as handle:
            head = [next(handle, "") for _ in range(5)]
    except OSError:
        return None
    if any(GENERATED_HEADER_RE.search(line) for line in head):
        return "generated file (says so in its header)"
    return None


def path_signals(path: str) -> list[str]:
    found = []
    if MIGRATION_RE.search("/" + path):
        found.append("migration")
    if "/settings/" in path:
        found.append("settings file")
    if "/graphql/" in path:
        found.append("GraphQL")
    if m := re.search(r"plugins/clients/([^/]+)/", path):
        found.append(f"client: {m[1]}")
    elif m := re.search(r"plugins/territories/([^/]+)/", path):
        found.append(f"territory: {m[1]}")
    elif not is_test(path) and re.match(
        r"src/(octoenergy/(domain|application|data|interfaces)|kraken)/|src/octoenergy/plugins/common/",
        path,
    ):
        found.append("shared code")
    return found


def _signals(path: str, changed: list[dict]) -> list[dict]:
    signals: list[dict[str, Any]] = [{"label": label} for label in path_signals(path)]
    for label, pattern in LINE_SIGNAL_RES.items():
        hits = [line for line in changed if not line["moved"] and pattern.search(line["text"])]
        if hits:
            signals.append(
                {
                    "label": label,
                    "count": len(hits),
                    "lines": [f"{'R' if h['side'] == '+' else 'L'}{h['line']}" for h in hits[:5]],
                }
            )
    return signals


def _mechanical_reason(f: dict) -> str | None:
    """Why the change can't alter behaviour, or None when it might.

    A "generated" header is written by the PR author like any other line, so it's only a hint
    for the agents, never a reason on its own.
    """
    if f["generated"] and f["generated"].startswith("lockfile"):
        return f["generated"]
    if f["binary"]:
        return None
    if f["status"] == "R" and f["additions"] + f["deletions"] == 0:
        return "pure rename, content unchanged"
    if f["status"] in ("M", "T") and f["additions"] + f["deletions"] == 0:
        return "file mode change only"
    if f["status"] in ("M", "R") and f["substantive_lines"] == 0 and f["moved_lines"] == 0:
        return "only trailing whitespace or blank lines"
    return None


def _changed_files(repo: Path, base: str, head: str) -> list[dict]:
    common = ["git", "-C", str(repo), "-c", "core.quotePath=false", "diff", "-z", "-M"]
    statuses = run([*common, "--name-status", base, head]).split("\0")
    numstats = run([*common, "--numstat", base, head]).split("\0")

    files: list[dict] = []
    i = 0
    while i < len(statuses) - 1:
        code = statuses[i]
        if code[:1] in ("R", "C"):
            old, new = statuses[i + 1], statuses[i + 2]
            i += 3
        else:
            old = new = statuses[i + 1]
            i += 2
        files.append(
            {
                "path": new,
                "old_path": old if old != new else None,
                "status": code[:1],
                "similarity": int(code[1:]) if code[1:].isdigit() else None,
            }
        )

    counts: dict[str, tuple[int, int, bool]] = {}
    i = 0
    while i < len(numstats):
        token = numstats[i]
        if not token:
            i += 1
            continue
        added, deleted, path = token.split("\t", 2)
        if not path:  # a rename: the old and new paths follow as separate fields
            path = numstats[i + 2]
            i += 3
        else:
            i += 1
        binary = added == "-"
        counts[path] = (
            0 if binary else int(added),
            0 if binary else int(deleted),
            binary,
        )

    for f in files:
        added, deleted, binary = counts.get(f["path"], (0, 0, False))
        f |= {"additions": added, "deletions": deleted, "binary": binary}
    return files


def _changed_lines(repo: Path, base: str, head: str) -> dict[str, list[dict]]:
    """Each changed line per file, ignoring cosmetic whitespace, and whether git saw it move."""
    config = [arg for item in COLOUR_CONFIG for arg in ("-c", item)]
    diff = run(
        [
            "git",
            "-C",
            str(repo),
            *config,
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "-M",
            "--src-prefix=a/",
            "--dst-prefix=b/",
            "--color=always",
            "--color-moved=blocks",
            *COSMETIC_FLAGS,
            base,
            head,
        ]
    )
    lines: dict[str, list[dict]] = {}
    current: list[dict] | None = None
    old_path = new_path = None
    in_header = False
    old = new = 0
    for raw in diff.splitlines():
        plain = ANSI_RE.sub("", raw)
        if plain.startswith("diff --git "):
            in_header, current, old_path, new_path = True, None, None, None
            continue
        if in_header:
            if plain.startswith("--- "):
                old_path = _strip_prefix(plain[4:], "a/")
            elif plain.startswith("+++ "):
                new_path = _strip_prefix(plain[4:], "b/")
                current = lines.setdefault(new_path or old_path or "", [])
            elif m := HUNK_RE.match(plain):
                in_header = False
                old, new = int(m[1]), int(m[2])
            continue
        if m := HUNK_RE.match(plain):
            old, new = int(m[1]), int(m[2])
            continue
        if current is None:
            continue
        if coloured := COLOURED_LINE_RE.match(raw):
            side = coloured[2]
            current.append(
                {
                    "side": side,
                    "line": new if side == "+" else old,
                    "moved": coloured[1] in MOVED_COLOURS,
                    "text": plain[1:],
                }
            )
            if side == "+":
                new += 1
            else:
                old += 1
        elif plain.startswith(" "):
            old += 1
            new += 1
    return lines


def _strip_prefix(path: str, prefix: str) -> str | None:
    path = path.rstrip("\t")
    if path == "/dev/null":
        return None
    return path.removeprefix(prefix)
